## Enhancement 2: Percentage-Based Chart/Oscillator Splits

### Overview
Currently oscillators use fixed pixel heights (120px each). This should be percentage-based so the layout adapts better to different screen sizes:
- 1 oscillator: Chart 70%, Oscillator 30%
- 2 oscillators: Chart 60%, Each oscillator 20%
- 3 oscillators: Chart 40%, Each oscillator 20%

### Files to Modify

#### 1. `client/src/lib/constants/layout.ts`

**Add new constants:**

```typescript
// Percentage-based oscillator sizing
export const SINGLE_OSCILLATOR_PERCENT = 30; // Chart 70%, Oscillator 30%
export const MULTI_OSCILLATOR_PERCENT_EACH = 20; // Each oscillator gets 20%
export const MAX_OSCILLATOR_TOTAL_PERCENT = 60; // Never more than 60% for oscillators
export const MIN_CHART_PERCENT = 40; // Chart always at least 40%
```

---

#### 2. `client/src/hooks/useOscillatorPanel.ts`

**Add percentage calculations:**

```typescript
import { 
  OSCILLATOR_PANEL_HEIGHT_PER,
  SINGLE_OSCILLATOR_PERCENT,
  MULTI_OSCILLATOR_PERCENT_EACH,
  MAX_OSCILLATOR_TOTAL_PERCENT,
  MIN_CHART_PERCENT
} from '@/lib/constants/layout';

// Update the return interface:
interface UseOscillatorPanelReturn {
  selectedOscillators: Set<string>;
  poppedOutOscillators: Set<string>;
  dockedCount: number;
  totalHeight: number;
  toggleOscillator: (id: string, mode?: OscillatorDisplayMode) => void;
  popoutOscillator: (id: string) => void;
  showSelector: boolean;
  setShowSelector: (show: boolean) => void;
  // NEW percentage-based values:
  totalPercentage: number;
  chartPercentage: number;
  perOscillatorPercentage: number;
}

// Add new useMemo calculations:
const totalPercentage = useMemo(() => {
  if (dockedCount === 0) return 0;
  if (dockedCount === 1) return SINGLE_OSCILLATOR_PERCENT;
  const multiPercent = dockedCount * MULTI_OSCILLATOR_PERCENT_EACH;
  return Math.min(multiPercent, MAX_OSCILLATOR_TOTAL_PERCENT);
}, [dockedCount]);

const chartPercentage = useMemo(() => {
  return Math.max(100 - totalPercentage, MIN_CHART_PERCENT);
}, [totalPercentage]);

const perOscillatorPercentage = useMemo(() => {
  if (dockedCount === 0) return 0;
  return totalPercentage / dockedCount;
}, [totalPercentage, dockedCount]);

// Update return to include new values:
return {
  selectedOscillators,
  poppedOutOscillators,
  dockedCount,
  totalHeight,
  toggleOscillator,
  popoutOscillator,
  showSelector,
  setShowSelector,
  totalPercentage,
  chartPercentage,
  perOscillatorPercentage,
};
```

---

#### 3. `client/src/components/oscillators/DockedOscillatorSection.tsx`

**Update to use percentage-based heights:**

```typescript
// Update interface:
interface DockedOscillatorSectionProps {
  selectedOscillators: Set<string>;
  poppedOutOscillators: Set<string>;
  oscillatorData: OscillatorData;
  candles: { time: number }[];
  totalOscillatorHeight: number;
  onPopout: (oscillatorId: string) => void;
  isFullscreen?: boolean;
  // NEW:
  usePercentage?: boolean;
  totalPercentage?: number;
  perOscillatorPercentage?: number;
}

// Update function params:
export function DockedOscillatorSection({
  selectedOscillators,
  poppedOutOscillators,
  oscillatorData,
  candles,
  totalOscillatorHeight,
  onPopout,
  isFullscreen = false,
  usePercentage = false,
  totalPercentage = 0,
  perOscillatorPercentage = 0,
}: DockedOscillatorSectionProps) {

// Update container style:
style={{ 
  bottom: isFullscreen ? 0 : `${MOBILE_NAV_HEIGHT}px`,
  height: usePercentage ? `${totalPercentage}vh` : `${totalOscillatorHeight}px`,
  maxHeight: `calc(100vh - ${isFullscreen ? 0 : MOBILE_NAV_HEIGHT}px - ${TOP_TOOLBAR_HEIGHT}px)`
}}

// Update each oscillator panel container:
// Change from:
<div style={{ height: `${OSCILLATOR_PANEL_HEIGHT_PER}px` }} className="p-2">
// To:
<div style={{ height: usePercentage ? `${perOscillatorPercentage}vh` : `${OSCILLATOR_PANEL_HEIGHT_PER}px` }} className="p-2">
```

